#ifndef CSM_SESSION_H
#define CSM_SESSION_H

#include <stddef.h>
#include <time.h>

/* Bytes read from each end of a .jsonl file; Claude Code reads the same. */
#define SESSION_CHUNK 65536

/* Longest first prompt Claude Code keeps, in characters, before "…". */
#define SESSION_PROMPT_MAX 200

/* The Claude Code version csm was last checked against. */
#define SESSION_TESTED_VERSION "2.1.322"

/* Where Claude Code keeps its data for this user. */
struct claude_paths {
	char *home;		/* NULL when unknown */
	char *config_dir;	/* $CLAUDE_CONFIG_DIR or ~/.claude */
	char *projects_dir;	/* <config_dir>/projects */
	char *config_file;	/* .claude.json */
};

/* One session file, as csm -s shows it. */
struct session_info {
	char *id;		/* file name without .jsonl */
	time_t started;		/* first message; 0 when unknown */
	time_t modified;	/* the file's mtime */
	size_t messages;
	char *branch;		/* last gitBranch; NULL when none */
	char *title;		/* name given with /rename; NULL when none */
	char *prompt;		/* first user prompt; NULL when none */
};

void claude_paths_init(struct claude_paths *p);
void claude_paths_free(struct claude_paths *p);
char *session_file_cwd(const char *file);
char *session_dir_cwd(const char *dir);
char **session_files(const char *dir, size_t *count);
void session_files_free(char **files, size_t count);
int session_info_read(const char *file, struct session_info *info);
void session_info_free(struct session_info *info);
int session_compare(const void *a, const void *b);
char *session_prompt(const char *text, char **fallback);
char *session_claude_version(const char *projects_dir);
int session_version_compare(const char *a, const char *b);

#endif
